use crate::{files::{args,path,text},text_tools::{boolean,number}};
use serde_json::{json,Value};
use std::{collections::BTreeMap,fs,io::{Read,Write},os::unix::{fs::{DirBuilderExt,OpenOptionsExt},process::{CommandExt,ExitStatusExt}},path::PathBuf,process::{Child,ChildStdin,Command,ExitStatus,Stdio},sync::{Arc,Mutex},thread,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};
const OUTPUT_LIMIT:usize=1024*1024;
const ENV_LIMIT:usize=1024*1024;
#[derive(Default)]struct Output{bytes:Vec<u8>,discarded:usize}
impl Output{fn take(&mut self)->(String,bool){let s=String::from_utf8_lossy(&self.bytes).into_owned();let t=self.discarded>0;self.bytes.clear();self.discarded=0;(s,t)}}
fn drain<R:Read+Send+'static>(mut r:R,out:Arc<Mutex<Output>>){thread::spawn(move||{let mut b=[0;8192];loop{let n=match r.read(&mut b){Ok(0)|Err(_)=>break,Ok(n)=>n};let mut o=out.lock().unwrap();let keep=n.min(OUTPUT_LIMIT.saturating_sub(o.bytes.len()));o.bytes.extend_from_slice(&b[..keep]);o.discarded+=n-keep;}});}
fn quote(s:&str)->String{format!("'{}'",s.replace('\'',"'\\''"))}
fn exit_code(status:ExitStatus)->i32{status.code().unwrap_or_else(||128+status.signal().unwrap_or(0))}
fn ident(name:&str)->bool{let mut chars=name.chars();match chars.next(){Some(c)if c.is_ascii_alphabetic()||c=='_'=>chars.all(|c|c.is_ascii_alphanumeric()||c=='_'),_=>false}}
// Re-applying these makes the next bash disagree with the cwd it was started in.
fn skipped_export(name:&str)->bool{matches!(name,"_"|"PWD"|"OLDPWD"|"SHLVL")}
struct Proc{child:Child,pid:i32,code:Option<i32>,reaped:bool}
impl Proc{
 fn poll(&mut self)->Result<(),String>{if self.reaped{return Ok(());}if let Some(status)=self.child.try_wait().map_err(|e|e.to_string())?{self.reaped=true;self.code=Some(exit_code(status));}Ok(())}
 fn kill(&mut self){if self.reaped{return;}unsafe{libc::kill(-self.pid,libc::SIGKILL);}if let Ok(status)=self.child.wait(){self.code=Some(exit_code(status));}self.reaped=true;}
}
struct Job{proc:Arc<Mutex<Proc>>,input:Option<ChildStdin>,output:Arc<Mutex<Output>>,command:String}
impl Drop for Job{fn drop(&mut self){self.proc.lock().unwrap().kill();}}
fn job_code(job:&Job)->Option<i32>{let mut proc=job.proc.lock().unwrap();let _=proc.poll();proc.code}
struct Report(PathBuf);
impl Drop for Report{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn read_regular(path:&PathBuf)->Result<Vec<u8>,String>{let file=fs::OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW).open(path).map_err(|e|e.to_string())?;let meta=file.metadata().map_err(|e|e.to_string())?;if !meta.is_file(){return Err("state report is not a regular file".into());}let mut data=Vec::new();file.take((ENV_LIMIT+1)as u64).read_to_end(&mut data).map_err(|e|e.to_string())?;if data.len()>ENV_LIMIT{return Err("state report is too large".into());}Ok(data)}
fn parse_env(bytes:&[u8])->BTreeMap<String,String>{let mut map=BTreeMap::new();let mut parts=bytes.split(|b|*b==0);while let Some(name)=parts.next(){let Some(value)=parts.next()else{break;};let name=String::from_utf8_lossy(name);if !ident(&name)||skipped_export(&name){continue;}map.insert(name.into_owned(),String::from_utf8_lossy(value).into_owned());}map}
fn valid_cwd(text:&str)->bool{let text=text.trim_end_matches(['\n','\r']);!text.is_empty()&&text.starts_with('/')&&!text.contains(['\n','\r','\0'])}
fn prelude(exports:&BTreeMap<String,String>)->String{let mut script=String::new();for(key,value)in exports{if ident(key)&&!skipped_export(key){script.push_str(&format!("export {key}={}\n",quote(value)));}}script}
pub struct Terminal{jobs:BTreeMap<String,Job>,next:u64,exports:BTreeMap<String,String>,cwd:String}
impl Terminal{
 pub fn new()->Self{Self{jobs:BTreeMap::new(),next:0,exports:BTreeMap::new(),cwd:std::env::current_dir().unwrap_or_default().to_string_lossy().into_owned()}}
 pub fn run(&mut self,v:&Value)->Result<Value,String>{args(v,&["command","workdir","timeout","background","pty"])?;let background=boolean(v,"background")?;if !background&&v.get("workdir").is_some_and(|w|!w.is_null()){return Err("foreground workdir is unsupported; use an explicit cd in the command (which changes the persistent shell), or use background=true with workdir".into());}if boolean(v,"pty")?{return Err("PTY is unsupported by standalone receiver; use a normal background pipe".into());}let command=text(v,"command")?;let timeout=number(v,"timeout",180,1800)?;if timeout==0{return Err("timeout must be positive".into());}let cwd=if let Some(w)=v.get("workdir").filter(|x|!x.is_null()){Some(path(w.as_str().ok_or("workdir must be string")?)?)}else{None};
 if let Some(w)=&cwd{if !w.is_dir(){return Err(format!("workdir is not a directory: {}",w.display()));}}
 // Each command is a fresh bash. Exit status comes from wait, not from anything
 // the command writes. Exports are parsed back into assignments and quoted on
 // the next command, so a command cannot plant a script in shell state.
 if background{return self.spawn(command,cwd,timeout as u64);}self.foreground(command,timeout as u64)}
 fn spawn(&mut self,command:&str,cwd:Option<PathBuf>,timeout:u64)->Result<Value,String>{let job_cwd=cwd.unwrap_or_else(||self.cwd.clone().into()).canonicalize().map_err(|e|format!("cannot resolve background workdir: {e}"))?;let script=format!("{}eval {}\n",prelude(&self.exports),quote(command));let mut cmd=Command::new("bash");cmd.args(["--noprofile","--norc","-c",&script]).current_dir(&job_cwd).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).process_group(0);let mut child=cmd.spawn().map_err(|e|e.to_string())?;let output=Arc::new(Mutex::new(Output::default()));drain(child.stdout.take().unwrap(),output.clone());drain(child.stderr.take().unwrap(),output.clone());let pid=child.id()as i32;let proc=Arc::new(Mutex::new(Proc{child,pid,code:None,reaped:false}));let timer=Arc::clone(&proc);thread::spawn(move||{thread::sleep(Duration::from_secs(timeout));timer.lock().unwrap().kill();});self.next+=1;let id=format!("job-{}",self.next);let input=proc.lock().unwrap().child.stdin.take();self.jobs.insert(id.clone(),Job{proc,input,output,command:command.into()});Ok(json!({"session_id":id,"pid":pid,"status":"running","cwd":job_cwd}))}
 fn foreground(&mut self,command:&str,timeout:u64)->Result<Value,String>{let report=self.report_dir()?;let pwd_file=report.0.join("pwd");let env_file=report.0.join("env");let script=format!("{prelude}{{ eval {command}; }} </dev/null\n__teleoperator_code=$?\npwd -L > {pwd}\ncompgen -e | while IFS= read -r __teleoperator_name; do printf '%s\\0%s\\0' \"$__teleoperator_name\" \"${{!__teleoperator_name}}\"; done > {env}\nexit $__teleoperator_code\n",prelude=prelude(&self.exports),command=quote(command),pwd=quote(&pwd_file.to_string_lossy()),env=quote(&env_file.to_string_lossy()));let mut cmd=Command::new("bash");cmd.args(["--noprofile","--norc","-c",&script]).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped()).process_group(0);if !self.cwd.is_empty(){cmd.current_dir(&self.cwd);}let mut child=cmd.spawn().map_err(|e|e.to_string())?;let output=Arc::new(Mutex::new(Output::default()));drain(child.stdout.take().unwrap(),output.clone());drain(child.stderr.take().unwrap(),output.clone());let pid=child.id()as i32;let started=Instant::now();let mut timed_out=false;let status=loop{match child.try_wait().map_err(|e|e.to_string())?{Some(status)=>break status,None if started.elapsed()>=Duration::from_secs(timeout)=>{timed_out=true;unsafe{libc::kill(-pid,libc::SIGKILL);}break child.wait().map_err(|e|e.to_string())?;}None=>{thread::sleep(Duration::from_millis(10));}}};thread::sleep(Duration::from_millis(20));let(text,truncated)=output.lock().unwrap().take();let mut updated=false;if !timed_out&&status.signal().is_none(){if let Ok(bytes)=read_regular(&pwd_file){let cwd=String::from_utf8_lossy(&bytes);let cwd=cwd.trim_end_matches(['\n','\r']);if valid_cwd(cwd){self.cwd=cwd.to_string();updated=true;}}if let Ok(bytes)=read_regular(&env_file){let parsed=parse_env(&bytes);if !parsed.is_empty(){self.exports=parsed;updated=true;}}}Ok(json!({"output":text,"exit_code":exit_code(status),"timed_out":timed_out,"truncated":truncated,"cwd":self.cwd,"shell_reset":timed_out||!updated}))}
 fn report_dir(&self)->Result<Report,String>{let nanos=SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos();let dir=std::env::temp_dir().join(format!("teleoperator-{}-{}",std::process::id(),nanos));fs::DirBuilder::new().recursive(true).mode(0o700).create(&dir).map_err(|e|e.to_string())?;Ok(Report(dir))}
 pub fn manage(&mut self,v:&Value)->Result<Value,String>{args(v,&["action","session_id","timeout","data","text"])?;let action=text(v,"action")?;if action=="list"{if v.as_object().unwrap().len()!=1{return Err("list accepts only action".into());}let mut rows=Vec::new();for(id,job)in &mut self.jobs{let code=job_code(job);rows.push(json!({"session_id":id,"pid":job.proc.lock().unwrap().pid,"command":job.command,"status":if code.is_some(){"exited"}else{"running"},"exit_code":code}));}return Ok(json!({"sessions":rows}));}let id=text(v,"session_id")?;let job=self.jobs.get_mut(id).ok_or("Unknown session_id")?;
 match action{"status"|"poll"=>{args(v,&["action","session_id"])?;let _=job_code(job);},"wait"=>{args(v,&["action","session_id","timeout"])?;let end=Instant::now()+Duration::from_secs(number(v,"timeout",30,1800)? as u64);loop{if job_code(job).is_some()||Instant::now()>=end{break;}thread::sleep(Duration::from_millis(10));}},"kill"=>{args(v,&["action","session_id"])?;job.proc.lock().unwrap().kill();job.input.take();},"write"|"submit"=>{args(v,&["action","session_id","data","text"])?;if v.get("data").is_some()&&v.get("text").is_some(){return Err("Use data or text, not both".into());}if job_code(job).is_some(){return Err("Job stdin is closed".into());}let data=v.get("data").or_else(||v.get("text")).and_then(Value::as_str).ok_or("data or text must be a string")?;let input=job.input.as_mut().ok_or("Job stdin is closed")?;input.write_all(data.as_bytes()).and_then(|_|if action=="submit"{input.write_all(b"\n")}else{Ok(())}).and_then(|_|input.flush()).map_err(|e|e.to_string())?;},_=>return Err(format!("Unsupported process action: {action}"))}
 thread::sleep(Duration::from_millis(10));let code=job_code(job);if code.is_some(){job.input.take();}let(output,truncated)=if action=="status"||action=="write"||action=="submit"{(String::new(),false)}else{job.output.lock().unwrap().take()};Ok(json!({"session_id":id,"pid":job.proc.lock().unwrap().pid,"status":if code.is_some(){"exited"}else{"running"},"exit_code":code,"output":output,"truncated":truncated}))}
}
